import React, { useEffect, useRef } from 'react'
import "./network-error.css"
import Button from '../ui/Button'

const NetworkError = ({small}) => {
    const buttonRef = useRef()
    useEffect(() => {
        buttonRef?.current?.focus()
    }, [])

    if(small){
        return <aside className="network-error">
            <div className="small-error-content">
                <h2 className="small-error-title">No internet.</h2>
                <p className="small-error-message">
                    Looks like you lost your connection. Please check it and try again.
                </p>
                <Button
                    text={"Try again"}
                    className={"small-error-button"}
                    handleEvent={() => window.location.reload()}
                />
            </div>
        </aside>
    }
    
    return (
        <section className="error-page">
            <article className="error-page">
                <svg className="error-svg" aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 512" fill="#FF2828">
                    <path d="M54.2 202.9C123.2 136.7 216.8 96 320 96s196.8 40.7 265.8 106.9c12.8 12.2 33 11.8 45.2-.9s11.8-33-.9-45.2C549.7 79.5 440.4 32 320 32S90.3 79.5 9.8 156.7C-2.9 169-3.3 189.2 8.9 202s32.5 13.2 45.2 .9zM320 256c56.8 0 108.6 21.1 148.2 56c13.3 11.7 33.5 10.4 45.2-2.8s10.4-33.5-2.8-45.2C459.8 219.2 393 192 320 192s-139.8 27.2-190.5 72c-13.3 11.7-14.5 31.9-2.8 45.2s31.9 14.5 45.2 2.8c39.5-34.9 91.3-56 148.2-56zm64 160a64 64 0 1 0 -128 0 64 64 0 1 0 128 0z"/>
                </svg>

                <div className="error-content">
                    <h2 className="error-title">No internet.</h2>
                    <p className="error-message">
                        Looks like you lost your connection. Please check it and try again.
                    </p>
                    <Button
                        text={"Try again"}
                        className={"error-button"}
                        ref={buttonRef}
                        handleEvent={() => window.location.reload()}
                    />
                </div>
            </article>
        </section>
    )
}

export default NetworkError
