import React, { useState } from 'react'
import "./user-sidebar.css"
import { useDispatch, useSelector } from 'react-redux'
import { selectBio } from '../../services/bio/reducers/bioSlice'
import { getCurrentUser } from '../../libs/getCurrentUser'
import { NavLink } from 'react-router-dom'
import Button from '../ui/Button'
import ConfirmationModal from '../confirmationModal/ConfirmationModal'
import { logoutAction } from '../../features/authentication/actions/authAction'

const UserSidebar = ({setShowUserSidebar}) => {
  const [showConfirmationModal, setshowConfirmationModal] = useState(false)
    const currentUserBio = useSelector(selectBio)
    const dispatch = useDispatch()
    const currentUser = getCurrentUser()

    const userBio =  currentUserBio?.find(bio => bio?.user._id === currentUser.userUid)

    const logUserOut = async () => {
      try{
        const payload = {
          method: "GET",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${currentUser.userToken}
            `,
          },
        };
        dispatch(logoutAction(payload))
      }
      catch(error){
        console.log(error)
      }
      finally{
        // dispatch(setErrorStatus(null))
      }
    }

  return (
    <aside className="user-sidebar" onClick={() => setShowUserSidebar(false)}>
        {showConfirmationModal && <ConfirmationModal ariaLabel={"Click to logout from Ventmoir"} onConfirm={logUserOut} onCancel={() => setshowConfirmationModal(false)} heading={"Do you want to logout?"} />}

        <div className="user-sidebar">
          <NavLink className="user-sidebar" to={`profile/${currentUser.userName}`}>
              <img className="user-sidebar" src={userBio?.avatar} alt={`${currentUser?.userName} profile avatar`} />
              <h2 className="user-sidebar">{currentUser?.userName}</h2>
              <small className="user-sidebar">View profile</small>
          </NavLink>

          <ul className="user-sidebar-list">
              <li className="user-sidebar-list-item">
                  <NavLink to={"/settings"}>
                    <svg xmlns="http://www.w3.org/2000/svg" width="28" height="26" viewBox="0 0 28 26" fill="none">
                      <path d="M21.3846 2.4566L21.385 2.45682C22.2492 2.94149 22.5377 4.01342 22.0488 4.85437C21.36 6.0337 21.2031 7.28119 21.7923 8.28039C22.3785 9.27464 23.5474 9.7569 24.9228 9.7569C25.9333 9.7569 26.7387 10.5688 26.75 11.5271V13.8539C26.75 14.8145 25.9413 15.62 24.9363 15.62C23.5614 15.62 22.3914 16.1021 21.8068 17.0978C21.219 18.0987 21.3815 19.3469 22.0774 20.5255C22.5629 21.3509 22.2772 22.4349 21.412 22.9201L21.4116 22.9204L19.0773 24.2314L19.0772 24.2313L19.0663 24.2377C18.3639 24.6478 17.4397 24.4077 17.0115 23.7054L16.8656 23.4581L16.8654 23.4578C16.1684 22.2774 15.1529 21.5298 13.9949 21.5298C12.8363 21.5298 11.824 22.2782 11.1335 23.4595C11.1333 23.46 11.133 23.4604 11.1327 23.4609L10.9885 23.7054C10.5602 24.4077 9.6361 24.6478 8.93365 24.2377L8.9337 24.2376L8.92274 24.2314L6.58841 22.9204L6.58801 22.9201C5.72411 22.4356 5.43546 21.3643 5.92374 20.5234C6.61865 19.3455 6.78062 18.0981 6.19323 17.0978C5.60862 16.1021 4.43859 15.62 3.06372 15.62C2.05043 15.62 1.25 14.8063 1.25 13.8539V11.5231C1.25 10.5625 2.05875 9.7569 3.06372 9.7569C4.43849 9.7569 5.60811 9.27498 6.19283 8.28154C6.78073 7.2827 6.61889 6.03814 5.92328 4.86597C5.43467 4.02358 5.72606 2.94023 6.58801 2.45682L6.58841 2.4566L8.92274 1.14553L8.92279 1.14562L8.93365 1.13928C9.64216 0.725584 10.5579 0.976288 10.9563 1.66267L10.9563 1.66268L10.959 1.66726L11.1074 1.91887L11.1076 1.9192C11.8046 3.09952 12.8201 3.84719 13.9781 3.84719C15.1368 3.84719 16.1491 3.09871 16.8396 1.91729C16.8398 1.91689 16.84 1.91648 16.8403 1.91608L16.9845 1.67152C17.4128 0.96929 18.3369 0.729121 19.0394 1.13928L19.0393 1.13938L19.0503 1.14553L21.3846 2.4566ZM8.85795 12.6885C8.85795 15.4864 11.177 17.7425 13.9933 17.7425C16.8095 17.7425 19.1286 15.4864 19.1286 12.6885C19.1286 9.89058 16.8095 7.63448 13.9933 7.63448C11.177 7.63448 8.85795 9.89058 8.85795 12.6885Z" stroke="black" strokeWidth="1.5"/>
                    </svg>
                    <p>Settings</p>
                  </NavLink>
              </li>

              <li className="user-sidebar-list-item">
                  <Button
                    handleEvent={(e) => {
                    e.stopPropagation()
                    setshowConfirmationModal(true)}}
                    keyDownEvent={logUserOut}
                    ariaLabel={"Click to open logout confirmation modal"}
                    text={
                      <>
                        <svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" width="29" height="29" viewBox="0 0 29 29" fill="none">
                          <path d="M18.9247 28.2451H18.7471C12.6823 28.2451 9.75913 25.8547 9.25372 20.5002C9.19909 19.9401 9.60887 19.4347 10.1826 19.3801C10.729 19.3255 11.248 19.7489 11.3026 20.309C11.6988 24.598 13.7204 26.1962 18.7607 26.1962H18.9383C24.4977 26.1962 26.4647 24.2292 26.4647 18.6698V9.76379C26.4647 4.20437 24.4977 2.2374 18.9383 2.2374H18.7607C13.6931 2.2374 11.6715 3.86288 11.3026 8.23392C11.2344 8.79396 10.7563 9.21741 10.1826 9.16277C9.60887 9.12179 9.19909 8.61639 9.24007 8.05635C9.70449 2.61987 12.6413 0.188477 18.7471 0.188477H18.9247C25.6315 0.188477 28.5 3.05697 28.5 9.76379V18.6698C28.5 25.3766 25.6315 28.2451 18.9247 28.2451Z" fill="#292D32"/>
                          <path d="M18.5949 15.2413H3.05046C2.49042 15.2413 2.026 14.7769 2.026 14.2168C2.026 13.6568 2.49042 13.1924 3.05046 13.1924H18.5949C19.155 13.1924 19.6194 13.6568 19.6194 14.2168C19.6194 14.7769 19.155 15.2413 18.5949 15.2413Z" fill="#292D32"/>
                          <path d="M6.09698 19.8175C5.83745 19.8175 5.57792 19.7219 5.37303 19.517L0.797094 14.9411C0.400969 14.5449 0.400969 13.8893 0.797094 13.4932L5.37303 8.91721C5.76915 8.52109 6.42481 8.52109 6.82094 8.91721C7.21706 9.31334 7.21706 9.96899 6.82094 10.3651L2.96896 14.2171L6.82094 18.0691C7.21706 18.4652 7.21706 19.1209 6.82094 19.517C6.6297 19.7219 6.35651 19.8175 6.09698 19.8175Z" fill="#292D32"/>
                        </svg>
                        <p>Logout</p>
                      </>
                    }
                  />
              </li>
          </ul>
        </div>
    </aside>
  )
}

export default UserSidebar
