import React, { lazy, useEffect } from 'react'
import "./home.css"
import { HomeWidget, UserPost, fetchPosts } from '../../features/home/index'
import { useDispatch, useSelector } from 'react-redux'
import { getCurrentUser } from '../../libs/getCurrentUser'
import { useNavigate } from 'react-router-dom'
import { getPostError, getPostStatus, selectAllPosts } from '../../services/post/reducers/postSlice'
import { selectAuthenticatedUser } from '../../features/authentication/reducers/authSlice'
import { getFetch } from '../../libs/fetch'
import { API_URL } from '../../services/api'

const NetworkError = lazy(() => import('../../components/networkError/NetworkError'))
const Home = () => {
  const authenticatedUser = useSelector(selectAuthenticatedUser)
  const navigate = useNavigate()
  const currentUser = getCurrentUser()
  const postErrorStatus = useSelector(getPostError)
  const postStatus = useSelector(getPostStatus)
  const allPosts = useSelector(selectAllPosts)

  const refreshToken = async () => {
    try {
      const res = await fetch(`${API_URL}/user/refresh_token`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        credentials: "include"
      });
  
      const data = await res.json(); // parse the response body
      console.log(data, "refresh data");
      console.log(res)
    } catch (error) {
      console.error("Error refreshing token:", error);
    }
  };
  

  useEffect(() => {
    console.log("effect refresh")
    refreshToken();
  }, []);

  useEffect(() => {
    if (Object.keys(currentUser).length === 0) {
      navigate("/login")
    }
  }, [])
  
  useEffect(() => {
    if(!allPosts.length &&  postStatus === "idle"){
      window.location.reload()
    } 
  }, [])
  

  if(!navigator.onLine){
    return <NetworkError />
  }

  if(authenticatedUser[0]?.existingUser?.isNewUser){
    navigate("/onboarding")
  }

  return (
    <main className="home-container">
      <div className="home-layout">
        <UserPost />
      </div>
      <HomeWidget />
    </main>
  )
}

export default Home